alter table public.cargo_release_pick_events add column if not exists cargo_unit_label_id uuid references public.cargo_unit_labels(id);
create unique index if not exists uq_active_cr_pick_label on public.cargo_release_pick_events(cargo_unit_label_id) where cargo_unit_label_id is not null and reversed_at is null;
create or replace function public.record_cargo_release_label_pick(p_line_id uuid,p_tracking_code text) returns uuid language plpgsql security invoker set search_path=public as $$
declare l cargo_release_lines%rowtype;lab cargo_unit_labels%rowtype;ev uuid;total numeric;
begin select * into l from cargo_release_lines where id=p_line_id for update;if not found then raise exception 'Release line not found';end if;select * into lab from cargo_unit_labels where cargo_unit_id=l.cargo_unit_id and lower(tracking_code)=lower(trim(p_tracking_code));if not found then raise exception 'This label does not belong to the allocated cargo';end if;if exists(select 1 from cargo_release_pick_events where cargo_unit_label_id=lab.id and reversed_at is null) then raise exception 'This physical unit has already been picked';end if;total:=coalesce(l.picked_quantity,0)+1;if total>l.requested_quantity then raise exception 'This line is already fully picked';end if;insert into cargo_release_pick_events(organization_id,cargo_release_id,cargo_release_line_id,cargo_unit_id,cargo_unit_label_id,quantity,method,scanned_value,location_id) select l.organization_id,l.cargo_release_id,l.id,l.cargo_unit_id,lab.id,1,'SCAN',lab.tracking_code,c.warehouse_location_id from cargo_units c where c.id=l.cargo_unit_id returning id into ev;update cargo_release_lines set picked_quantity=total,pick_status=case when total=l.requested_quantity then 'PICKED' else 'PARTIAL' end,picked_at=now(),picked_by=auth.uid() where id=l.id;return ev;end $$;
grant execute on function public.record_cargo_release_label_pick(uuid,text) to authenticated;